import { Component, OnInit, OnDestroy } from '@angular/core';
import { CommonModule } from '@angular/common';
import { RouterModule } from '@angular/router';
import { Subscription } from 'rxjs';
import { ApiService } from '../../core/services/api.service';
import { WebSocketService } from '../../core/services/websocket.service';
import { ToastService } from '../../core/services/toast.service';

@Component({
  selector: 'app-dashboard',
  standalone: true,
  imports: [CommonModule, RouterModule],
  template: `
    <div class="page-container">
      <div class="page-header">
        <h1 class="page-title">// vue_ensemble</h1>
        <p class="page-subtitle">État global de la plateforme DevSecOps IA — Vermeg</p>
      </div>

      <!-- Loading -->
      <div *ngIf="!stats" class="loading-overlay">
        <div class="spinner"></div>
        <span>Chargement des données...</span>
      </div>

      <ng-container *ngIf="stats">
        <!-- KPIs -->
        <div class="kpi-grid">
          <div class="kpi-card blue">
            <div class="kpi-label">Projets actifs</div>
            <div class="kpi-value">{{stats.totalProjects}}</div>
            <div class="kpi-sub">Sous surveillance IA</div>
          </div>
          <div class="kpi-card red" [class.pulse-critical]="stats.openIncidents > 10">
            <div class="kpi-label">Incidents ouverts</div>
            <div class="kpi-value">{{stats.openIncidents}}</div>
            <div class="kpi-sub">En cours de traitement</div>
          </div>
          <div class="kpi-card orange">
            <div class="kpi-label">Incidents critiques</div>
            <div class="kpi-value">{{stats.criticalIncidents}}</div>
            <div class="kpi-sub">Attention immédiate requise</div>
          </div>
          <div class="kpi-card green">
            <div class="kpi-label">Corrections IA</div>
            <div class="kpi-value">{{stats.totalCorrections}}</div>
            <div class="kpi-sub">Pull Requests créées</div>
          </div>
          <div class="kpi-card purple">
            <div class="kpi-label">Temps économisé</div>
            <div class="kpi-value">{{stats.timeSavedHours}}h</div>
            <div class="kpi-sub">Ce mois-ci</div>
          </div>
          <div class="kpi-card blue">
            <div class="kpi-label">Score santé moyen</div>
            <div class="kpi-value">{{stats.avgHealthScore | number:'1.0-0'}}%</div>
            <div class="kpi-sub">Tous projets confondus</div>
          </div>
        </div>

        <!-- Main grid -->
        <div class="grid-2" style="margin-bottom:16px;">

          <!-- Projects -->
          <div class="card">
            <div class="card-header">
              <span class="card-title">Projets</span>
              <a routerLink="/projects" class="btn btn-secondary btn-sm">Voir tous →</a>
            </div>
            <div *ngIf="projects.length === 0" class="empty-state" style="padding:24px;">
              <div class="empty-icon">◧</div>
              <div class="empty-title">Aucun projet</div>
            </div>
            <div *ngFor="let p of projects.slice(0,5)" class="project-row">
              <div class="health-dot" [style.background]="getHealthColor(p.healthScore)"></div>
              <div style="flex:1;min-width:0;">
                <a [routerLink]="['/projects', p.id]" class="project-name">{{p.name}}</a>
                <div class="project-meta">{{p.openIncidents}} incidents ouverts</div>
              </div>
              <div style="text-align:right;">
                <div class="health-score" [style.color]="getHealthColor(p.healthScore)">
                  {{p.healthScore | number:'1.0-0'}}%
                </div>
                <div style="font-size:9px;color:var(--text-faint);">santé</div>
              </div>
            </div>
          </div>

          <!-- Live feed -->
          <div class="card">
            <div class="card-header">
              <span class="card-title">Flux temps réel</span>
              <div class="live-indicator">
                <div class="live-dot"></div> Live
              </div>
            </div>
            <div *ngIf="liveEvents.length === 0" class="empty-state" style="padding:24px;">
              <div class="empty-icon">📡</div>
              <div class="empty-title">En attente d'événements</div>
              <div class="empty-sub">Les incidents s'afficheront ici</div>
            </div>
            <div *ngFor="let e of liveEvents.slice(0,7)" class="event-row">
              <span class="badge {{e.severity?.toLowerCase()}}">{{e.severity}}</span>
              <div style="flex:1;min-width:0;">
                <div class="event-title">{{e.title}}</div>
                <div class="event-meta">{{e.projectName}} · {{e.timestamp | date:'HH:mm:ss'}}</div>
              </div>
              <span class="badge {{e.status?.toLowerCase()}}">{{e.status}}</span>
            </div>
          </div>
        </div>

        <!-- Agent performance -->
        <div class="card" style="margin-bottom:16px;" *ngIf="agentStats">
          <div class="card-header">
            <span class="card-title">Performance des agents IA</span>
          </div>
          <div style="display:grid;grid-template-columns:repeat(4,1fr);gap:16px;">
            <div *ngFor="let a of agentStats" class="agent-card">
              <div class="agent-header">
                <span class="agent-icon" [style.color]="a.color" [style.background]="a.color+'11'">{{a.icon}}</span>
                <span class="agent-name">{{a.name}}</span>
              </div>
              <div class="agent-score" [style.color]="a.color">{{a.score}}%</div>
              <div class="agent-bar">
                <div class="agent-fill" [style.width]="a.score+'%'" [style.background]="a.color"></div>
              </div>
              <div class="agent-meta">{{a.count}} analyses</div>
            </div>
          </div>
        </div>

        <!-- ROI Banner -->
        <div class="roi-banner">
          <div>
            <div class="roi-title">Impact de la plateforme ce mois</div>
            <div class="roi-desc">
              {{stats.totalCorrections}} corrections automatiques ·
              {{stats.timeSavedHours}}h économisées ·
              {{stats.criticalIncidents}} failles détectées avant production
            </div>
          </div>
          <div style="text-align:right;">
            <div class="roi-score">{{stats.avgHealthScore | number:'1.0-0'}}%</div>
            <div style="font-size:11px;color:var(--text-muted);">score qualité global</div>
          </div>
        </div>
      </ng-container>
    </div>
  `,
  styles: [`
    .project-row {
      display: flex;
      align-items: center;
      gap: 10px;
      padding: 10px 0;
      border-bottom: 1px solid var(--border);
      &:last-child { border-bottom: none; }
    }

    .health-dot {
      width: 7px; height: 7px;
      border-radius: 50%;
      flex-shrink: 0;
    }

    .project-name {
      font-size: 12px;
      font-weight: 500;
      color: var(--text-secondary);
      text-decoration: none;
      display: block;
      overflow: hidden;
      text-overflow: ellipsis;
      white-space: nowrap;
      &:hover { color: var(--accent-blue); }
    }

    .project-meta { font-size: 10px; color: var(--text-faint); }
    .health-score { font-size: 15px; font-weight: 700; font-family: var(--font-mono); }

    .event-row {
      display: flex;
      align-items: center;
      gap: 8px;
      padding: 8px 0;
      border-bottom: 1px solid var(--border);
      &:last-child { border-bottom: none; }
    }

    .event-title {
      font-size: 11px;
      font-weight: 500;
      color: var(--text-secondary);
      overflow: hidden;
      text-overflow: ellipsis;
      white-space: nowrap;
    }

    .event-meta { font-size: 10px; color: var(--text-faint); font-family: var(--font-mono); }

    .agent-card { display: flex; flex-direction: column; gap: 8px; }

    .agent-header {
      display: flex;
      align-items: center;
      gap: 8px;
    }

    .agent-icon {
      width: 28px; height: 28px;
      border-radius: var(--radius-sm);
      display: flex;
      align-items: center;
      justify-content: center;
      font-size: 14px;
      flex-shrink: 0;
    }

    .agent-name {
      font-size: 11px;
      color: var(--text-muted);
      font-family: var(--font-mono);
    }

    .agent-score {
      font-size: 22px;
      font-weight: 700;
      font-family: var(--font-mono);
    }

    .agent-bar {
      height: 3px;
      background: var(--border);
      border-radius: 2px;
      overflow: hidden;
    }

    .agent-fill {
      height: 100%;
      border-radius: 2px;
      transition: width 0.8s ease;
    }

    .agent-meta { font-size: 10px; color: var(--text-faint); }

    .roi-banner {
      background: var(--bg-secondary);
      border: 1px solid var(--border);
      border-left: 3px solid var(--accent-blue);
      border-radius: var(--radius-lg);
      padding: 20px 24px;
      display: flex;
      align-items: center;
      justify-content: space-between;
    }

    .roi-title {
      font-size: 14px;
      font-weight: 600;
      color: var(--text-primary);
      margin-bottom: 4px;
      font-family: var(--font-mono);
    }

    .roi-desc { font-size: 12px; color: var(--text-muted); }

    .roi-score {
      font-size: 32px;
      font-weight: 700;
      color: var(--accent-blue);
      font-family: var(--font-mono);
    }
  `]
})
export class DashboardComponent implements OnInit, OnDestroy {
  stats: any     = null;
  projects: any[] = [];
  liveEvents: any[] = [];
  agentStats: any[] = [];
  private subs: Subscription[] = [];

  constructor(
    private api: ApiService,
    private ws: WebSocketService,
    private toast: ToastService
  ) {}

  ngOnInit() {
    this.loadData();
    this.ws.connect();
    this.subs.push(
      this.ws.incidentUpdates$.subscribe(event => {
        this.liveEvents.unshift({ ...event, timestamp: new Date() });
        if (this.liveEvents.length > 20) this.liveEvents.pop();
        if (event.severity === 'CRITICAL' || event.severity === 'HIGH') {
          this.toast.error('Nouvel incident', event.title || 'Incident détecté');
        }
        this.loadData();
      })
    );
  }

  loadData() {
    this.api.getGlobalStats().subscribe((s: any) => {
      this.stats = {
        totalProjects:     s.totalProjects    || 0,
        openIncidents:     s.totalBugs        || 0,
        criticalIncidents: s.criticalBugs     || 0,
        totalCorrections:  s.fixedBugs        || 0,
        timeSavedHours:    Math.round((s.fixedBugs || 0) * 0.5),
        avgHealthScore:    s.avgSecurityScore || 0
      };
      if (s.projects) {
        this.projects = s.projects.map((p: any) => ({
          ...p,
          healthScore:   p.securityScore || 0,
          openIncidents: 0
        }));
      }
    });
    this.agentStats = [
      { name: 'Root Cause',    icon: '◈', color: '#38bdf8', score: 92, count: 0 },
      { name: 'Security Risk', icon: '⬡', color: '#e24b4a', score: 88, count: 0 },
      { name: 'Remediation',   icon: '◆', color: '#22c55e', score: 85, count: 0 },
      { name: 'Judge Agent',   icon: '▣', color: '#f59e0b', score: 96, count: 0 },
    ];
  }

  getHealthColor(score: number): string {
    if (score >= 80) return 'var(--accent-green)';
    if (score >= 60) return 'var(--accent-orange)';
    return 'var(--accent-red)';
  }

  ngOnDestroy() { this.subs.forEach(s => s.unsubscribe()); }
}
